import type { ControlDef } from "./controls";
import type { Params } from "./effects";

export type OriginalEntry = {
  key: string;
  name: string;
  category: string;
  blurb: string;
  features: string[];
  controls: ControlDef[];
};

export function defaultsFrom(controls: ControlDef[]): Params {
  const p: Params = {};
  for (const c of controls) p[c.key] = c.default;
  return p;
}

